export function getBundledWiki(lang: string, topic: string): string | null {
  const cleanLang = (lang || 'en').toLowerCase().trim();
  const cleanTopic = topic.replace('.md', '').trim();
  const altUnderscore = cleanTopic.replace(/-/g, '_');
  const altDash = cleanTopic.replace(/_/g, '-');

  // 1. Try requested language
  if (BUNDLED_WIKI[cleanLang]) {
    const doc = BUNDLED_WIKI[cleanLang][cleanTopic] ||
                BUNDLED_WIKI[cleanLang][altUnderscore] ||
                BUNDLED_WIKI[cleanLang][altDash];
    if (doc) return doc;
  }

  // 2. Fallback to English
  if (BUNDLED_WIKI['en']) {
    const doc = BUNDLED_WIKI['en'][cleanTopic] ||
                BUNDLED_WIKI['en'][altUnderscore] ||
                BUNDLED_WIKI['en'][altDash];
    if (doc) return doc;
  }

  return null;
}
